// ============================================================================
// dd-credor — Etapa 2: qualifica TODOS os processos do credor (por CPF) pelo Manual de Due Diligência.
// Busca o processo na Judit (movimentações + documentos públicos), aplica o Manual
// via IA e devolve um veredito estruturado (🟢/🟡/🔴 + riscos com evidência).
//
// USO (navegador): ?cpf=CPF_SO_NUMEROS&max=6  -> lista + veredito de cada processo (usa Judit + IA por processo!).
// ============================================================================

import { corsHeaders } from "../_shared/cors.ts";
import { ERRO_ACESSO, getCallerAtivo, serviceClient } from "../_shared/auth.ts";
import { chaveJudit, chaveAnthropic, segredoGoogle } from "../_shared/segredos.ts";
import { PDFDocument, StandardFonts, rgb } from "npm:pdf-lib@1.17.1";

const CORS = corsHeaders;
const JUDIT_REQUESTS = "https://requests.prod.judit.io/requests";
const JUDIT_RESPONSES = "https://requests.prod.judit.io/responses";
const JUDIT_LAWSUITS = "https://lawsuits.production.judit.io/lawsuits";
const CLAUDE_MODEL = "claude-opus-4-5";
const MAX_DOC_CHARS = 380000;
const MAX_DOCS_BAIXAR = 20;
const POLL_MAX = 22;
const MANUAL_B64 = "";

const PALAVRAS_CHAVE = ["CALCULO","CONTA","DEMONSTRATIVO","MEMORIA","PLANILHA","DECISAO","SENTENCA","ACORDAO","HOMOLOG","REQUISICAO","RPV","PRECATORIO","OFICIO","ALVARA","PENHORA","BLOQUEIO","CESSAO","HABILITAC"];
const VALOR = ["CALCULO","CONTA","DEMONSTRATIVO","MEMORIA","REQUISICAO","RPV","PRECATORIO","PENHORA","CESSAO"];

function json(o: unknown, s = 200) { return new Response(JSON.stringify(o, null, 2), { status: s, headers: { ...CORS, "Content-Type": "application/json; charset=utf-8" } }); }
function safeParse(t: string) { try { return JSON.parse(t); } catch { return t; } }
function normalizar(s: string) { return (s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase(); }
function ehDocChave(n: string) { const x = normalizar(n); return PALAVRAS_CHAVE.some((p) => x.includes(p)); }
function ehValor(n: string) { const x = normalizar(n); return VALOR.some((p) => x.includes(p)); }
function fmtData(iso?: string) { if (!iso) return ""; const d = new Date(iso); return isNaN(d.getTime()) ? iso : d.toLocaleDateString("pt-BR"); }

async function montarTextoProcesso(juditKey: string, numero: string) {
  const postRes = await fetch(JUDIT_REQUESTS, { method: "POST", headers: { "api-key": juditKey, "Content-Type": "application/json" }, body: JSON.stringify({ search: { search_type: "lawsuit_cnj", search_key: numero }, with_attachments: true }) });
  const postJson = safeParse(await postRes.text());
  if (!postRes.ok) return { erro: "Judit recusou", resposta: postJson };
  const requestId = (postJson as any)?.request_id;
  if (!requestId) return { erro: "sem request_id", resposta: postJson };
  let resp: any = null, completo = false;
  for (let i = 0; i < POLL_MAX; i++) {
    await new Promise((r) => setTimeout(r, 2000));
    resp = safeParse(await (await fetch(`${JUDIT_RESPONSES}?request_id=${requestId}&page_size=100`, { headers: { "api-key": juditKey } })).text());
    const st = (resp as any)?.request_status;
    const pd: any[] = (resp as any)?.page_data || [];
    const temDoc = pd.some((it) => ((it.response_data?.attachments) || []).some((a: any) => a.status === "done" && !a.private && ehDocChave(a.attachment_name || "")));
    if (st === "completed") { completo = true; break; }
    if (temDoc && i >= 5) { completo = true; break; }
  }
  const pageData: any[] = (resp as any)?.page_data || [];
  if (!completo) return { aguarde: true };
  if (pageData.length === 0) return { nao_encontrado: true };
  const base = pageData[0].response_data || {};
  const movsMap = new Map<string, any>(); const anexos: any[] = []; const ids = new Set<string>();
  for (const item of pageData) {
    const d = item.response_data || {};
    for (const s of (d.steps || [])) { const k = `${s.step_date}|${(s.content || "").slice(0, 60)}`; if (!movsMap.has(k)) movsMap.set(k, s); }
    for (const a of (d.attachments || [])) { if (a.attachment_id && !ids.has(a.attachment_id)) { ids.add(a.attachment_id); anexos.push({ ...a, _inst: d.instance || 1 }); } }
  }
  const movs = Array.from(movsMap.values()).sort((a, b) => String(a.step_date).localeCompare(String(b.step_date)));
  const partes = (base.parties || []).map((p: any) => `- ${p.name} [${p.side === "Active" ? "POLO ATIVO" : p.side === "Passive" ? "POLO PASSIVO" : p.side}]${p.main_document ? ` (${p.main_document})` : ""}`).join("\n");
  let texto = `PROCESSO ${base.code || numero}\nTribunal: ${base.tribunal_acronym || ""} | Comarca: ${base.county || ""} | UF: ${base.state || ""}\nSituação: ${base.situation || ""} | Fase: ${base.phase || ""}\nValor da causa (inicial, NÃO é o valor do crédito): ${base.amount ?? "?"}\nPARTES:\n${partes}\n\n==== MOVIMENTAÇÕES (${movs.length}) ====\n` + movs.map((s) => `${fmtData(s.step_date)} — ${String(s.content || "").replace(/\s+/g, " ").trim()}`).join("\n") + `\n\n==== DOCUMENTOS ====\n`;
  const { extractText } = await import("npm:unpdf@1.6.2");
  const chaves = anexos.filter((a) => ehDocChave(a.attachment_name || "") && !a.corrupted).sort((a, b) => (ehValor(b.attachment_name || "") ? 1 : 0) - (ehValor(a.attachment_name || "") ? 1 : 0)).slice(0, MAX_DOCS_BAIXAR);
  const inacessiveis: string[] = [];
  for (const a of chaves) {
    if (texto.length > MAX_DOC_CHARS) break;
    try {
      const dl = await fetch(`${JUDIT_LAWSUITS}/${base.code || numero}/${a._inst}/attachments/${a.attachment_id}`, { headers: { "api-key": juditKey } });
      if (!dl.ok) { inacessiveis.push(`${a.attachment_name}${a.private ? " (SIGILOSO)" : ` (HTTP ${dl.status})`}`); continue; }
      const { text } = await extractText(new Uint8Array(await dl.arrayBuffer()), { mergePages: true });
      const t = Array.isArray(text) ? text.join("\n") : String(text || "");
      if (t.trim()) texto += `\n----- ${a.attachment_name} (${fmtData(a.attachment_date)}) -----\n${t.trim()}\n`;
    } catch (e) { inacessiveis.push(`${a.attachment_name} (erro)`); }
  }
  if (inacessiveis.length) texto += `\n\n==== DOCUMENTOS NÃO ACESSÍVEIS (sigilosos etc.) ====\nNÃO confira valores por estes; baseie-se no que está acessível e SINALIZE o que não deu pra ver:\n- ${inacessiveis.join("\n- ")}\n`;
  if (texto.length > MAX_DOC_CHARS) texto = texto.slice(0, MAX_DOC_CHARS) + "\n[...cortado...]";
  return { ok: true, texto, numero: base.code || numero, partes: (base.parties || []).map((p: any) => `${p.name} [${p.side}]`) };
}

async function qualificarPeloManual(apiKey: string, texto: string, numeroPrincipal: string) {
  const manual = new TextDecoder().decode(Uint8Array.from(atob(MANUAL_B64), (c) => c.charCodeAt(0)));
  const system = manual + `

===== CONTEXTO DA DUE DILIGENCE =====
Você está fazendo a due diligence dos processos de um CREDOR para avaliar o RISCO à aquisição de um CRÉDITO PRINCIPAL específico: o processo nº ${numeroPrincipal}.
O processo abaixo é UM DOS PROCESSOS DO CREDOR (pode ser o próprio crédito principal ou outro processo dele).
Sua tarefa: avaliar se ESTE processo representa um RISCO À AQUISIÇÃO DO CRÉDITO PRINCIPAL. São riscos ao crédito principal, por exemplo:
- Execução/dívida CONTRA o credor (ele no polo passivo devendo) → risco de penhora sobre o crédito principal;
- Cessão anterior do crédito principal a terceiro;
- Insolvência, falência ou indício de fraude do credor;
- Bloqueio/constrição que possa atingir o crédito principal.
ATENÇÃO CRÍTICA: um crédito DIFERENTE do credor (outra ação, já paga ou não, SEM relação com o principal) NÃO é risco ao crédito principal — é apenas INFORMAÇÃO para o histórico. NÃO classifique como risco algo que não ameaça o recebimento do crédito principal. Um crédito já pago do credor é bom sinal (histórico), não é risco.

===== FORMATO OBRIGATÓRIO DA RESPOSTA =====
Baseie-se APENAS no que está nos autos acessíveis; se algo estiver sigiloso/indisponível, diga que não pôde ser conferido — NUNCA invente datas, valores ou nomes.
A classificacao DEVE refletir o RISCO AO CRÉDITO PRINCIPAL e ser COERENTE com risco_ao_credito_principal:
- "🔴 Reprovada" = este processo representa risco IMPEDITIVO ao crédito principal (penhora provável, cessão anterior, insolvência, fraude);
- "🟡 Ressalvas" = ponto de atenção relacionado ao crédito principal, mas não impeditivo;
- "🟢 Aprovada" = NÃO representa risco ao crédito principal (inclui créditos diferentes/já pagos — que são apenas informação).
Responda APENAS com um JSON válido (sem markdown, sem texto antes ou depois):
{"classificacao":"🟢 Aprovada" | "🟡 Ressalvas" | "🔴 Reprovada","risco_ao_credito_principal":{"tem_risco":"SIM" | "NÃO","tipo":"penhora | cessão anterior | insolvência | fraude | bloqueio | outro | nenhum","justificativa":"documento/movimentação + data + trecho que comprova o risco; ou explique por que NÃO há risco ao principal"},"resumo":"1 a 3 frases: o que é este processo e sua relação (ou não) com o crédito principal","riscos":[{"risco":"descrição","fundamento":"documento/movimentação + data + trecho","grau":"Impeditivo | Elevado | Moderado | Ponto de atenção"}],"observacoes":"o que NÃO pôde ser conferido (documentos sigilosos etc.)"}`;
  const res = await fetch("https://api.anthropic.com/v1/messages", { method: "POST", headers: { "x-api-key": apiKey, "anthropic-version": "2023-06-01", "content-type": "application/json" }, body: JSON.stringify({ model: CLAUDE_MODEL, max_tokens: 4000, system, messages: [{ role: "user", content: texto }] }) });
  const j = await res.json();
  if (!res.ok) return { erro: "IA recusou", http: res.status, resposta: j };
  const txt = ((j?.content || []) as any[]).map((b) => b.text || "").join("").trim();
  const clean = txt.replace(/```json/gi, "").replace(/```/g, "").trim();
  try { return { ok: true, veredito: JSON.parse(clean) }; }
  catch { return { ok: false, texto_bruto: txt }; }
}

async function buscarProcessosPorCpf(juditKey: string, cpf: string) {
  const postRes = await fetch(JUDIT_REQUESTS, { method: "POST", headers: { "api-key": juditKey, "Content-Type": "application/json" }, body: JSON.stringify({ search: { search_type: "cpf", search_key: cpf }, with_attachments: false }) });
  const pj = safeParse(await postRes.text());
  if (!postRes.ok) return { erro: "Judit recusou a busca por CPF", resposta: pj };
  const requestId = (pj as any)?.request_id;
  if (!requestId) return { erro: "sem request_id", resposta: pj };
  let resp: any = null;
  for (let i = 0; i < 20; i++) {
    await new Promise((r) => setTimeout(r, 2000));
    resp = safeParse(await (await fetch(`${JUDIT_RESPONSES}?request_id=${requestId}&page_size=100`, { headers: { "api-key": juditKey } })).text());
    const st = (resp as any)?.request_status; const pd: any[] = (resp as any)?.page_data || [];
    if (st === "completed") break;
    if (pd.length > 0 && i >= 3) break;
  }
  const pd: any[] = (resp as any)?.page_data || [];
  const seen = new Set<string>(); const procs: any[] = [];
  for (const it of pd) {
    const d = it.response_data || {};
    if (d.code && !seen.has(d.code)) { seen.add(d.code); procs.push({ numero: d.code, tribunal: d.tribunal_acronym, valor_causa: d.amount, partes: (d.parties || []).map((p: any) => `${p.name} [${p.side}]`) }); }
  }
  return { ok: true, processos: procs };
}

/* ===== Google Drive (copiado da gerar-analise-rpv, comprovado) ===== */
const DRIVE_ROOT_NAME = "Credijuris - Atualizado";
const DRIVE_ANALISES_NAME = "A. Análises de crédito";
const FOLDER_MIME = "application/vnd.google-apps.folder";
interface DriveFile { id: string; name: string; mimeType?: string; parents?: string[]; }
function normDrive(s: string): string { return String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036F]/g, "").replace(/[.\-/() ]/g, ""); }
function escapeDriveQuery(s: string): string { return s.replace(/'/g, "\\'"); }
async function refreshGoogleAccessToken(clientId: string, clientSecret: string, refreshToken: string): Promise<string> {
  const res = await fetch("https://oauth2.googleapis.com/token", { method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" }, body: new URLSearchParams({ client_id: clientId, client_secret: clientSecret, refresh_token: refreshToken, grant_type: "refresh_token" }) });
  if (!res.ok) throw new Error(`Google OAuth (${res.status}): ${(await res.text()).slice(0, 200)}`);
  const data = await res.json(); if (!data.access_token) throw new Error("sem access_token"); return data.access_token as string;
}
async function driveListFiles(token: string, query: string): Promise<DriveFile[]> {
  const params = new URLSearchParams({ q: query, fields: "files(id,name,mimeType,parents)", includeItemsFromAllDrives: "true", supportsAllDrives: "true", pageSize: "1000", corpora: "allDrives" });
  const res = await fetch(`https://www.googleapis.com/drive/v3/files?${params}`, { headers: { Authorization: "Bearer " + token } });
  if (!res.ok) throw new Error(`Drive list (${res.status}): ${(await res.text()).slice(0, 200)}`);
  return (await res.json()).files || [];
}
async function driveFindSharedDrive(token: string, name: string): Promise<{ id: string; name: string } | null> {
  let pageToken: string | undefined;
  while (true) {
    const params = new URLSearchParams({ fields: "nextPageToken,drives(id,name)", pageSize: "100" });
    if (pageToken) params.set("pageToken", pageToken);
    const res = await fetch(`https://www.googleapis.com/drive/v3/drives?${params}`, { headers: { Authorization: "Bearer " + token } });
    if (!res.ok) return null;
    const data = await res.json();
    const found = (data.drives || []).find((d: any) => normDrive(d.name) === normDrive(name));
    if (found) return { id: found.id, name: found.name };
    if (!data.nextPageToken) return null; pageToken = data.nextPageToken;
  }
}
async function driveFindChild(token: string, name: string, parentId: string, mime?: string): Promise<DriveFile | null> {
  let q = `name = '${escapeDriveQuery(name)}' and '${parentId}' in parents and trashed = false`;
  if (mime) q += ` and mimeType = '${mime}'`;
  return (await driveListFiles(token, q))[0] || null;
}
async function driveCreateFolder(token: string, name: string, parentId: string): Promise<string> {
  const res = await fetch("https://www.googleapis.com/drive/v3/files?supportsAllDrives=true&fields=id", { method: "POST", headers: { Authorization: "Bearer " + token, "content-type": "application/json" }, body: JSON.stringify({ name, mimeType: FOLDER_MIME, parents: [parentId] }) });
  if (!res.ok) throw new Error(`Drive criar pasta '${name}' (${res.status}): ${(await res.text()).slice(0, 200)}`);
  return (await res.json()).id;
}
async function driveFindOrCreateFolder(token: string, name: string, parentId: string): Promise<string> {
  const ex = await driveFindChild(token, name, parentId, FOLDER_MIME); return ex ? ex.id : driveCreateFolder(token, name, parentId);
}
async function driveFindChildByTolerantName(token: string, parentId: string, needle: string): Promise<DriveFile | null> {
  const files = await driveListFiles(token, `'${parentId}' in parents and trashed = false and mimeType = '${FOLDER_MIME}'`);
  const n = normDrive(needle);
  return files.find((f) => normDrive(f.name) === n) ?? files.find((f) => normDrive(f.name).includes(n)) ?? null;
}
async function driveEncontrarAnalisesRoot(token: string): Promise<string> {
  const drive = await driveFindSharedDrive(token, DRIVE_ROOT_NAME);
  if (drive) { const c = await driveFindChildByTolerantName(token, drive.id, DRIVE_ANALISES_NAME); if (c) return c.id; throw new Error(`'${DRIVE_ANALISES_NAME}' não existe no shared drive`); }
  const roots = await driveListFiles(token, `name = '${escapeDriveQuery(DRIVE_ROOT_NAME)}' and trashed = false and mimeType = '${FOLDER_MIME}'`);
  if (!roots[0]) throw new Error(`'${DRIVE_ROOT_NAME}' não encontrado`);
  const c = await driveFindChildByTolerantName(token, roots[0].id, DRIVE_ANALISES_NAME);
  if (!c) throw new Error(`'${DRIVE_ANALISES_NAME}' não existe em '${DRIVE_ROOT_NAME}'`); return c.id;
}
async function driveUploadBytes(token: string, name: string, parentId: string, bytes: Uint8Array, mime: string): Promise<{ id: string; webViewLink?: string }> {
  const ex = await driveFindChild(token, name, parentId);
  if (ex) await fetch(`https://www.googleapis.com/drive/v3/files/${ex.id}?supportsAllDrives=true`, { method: "DELETE", headers: { Authorization: "Bearer " + token } });
  const boundary = "----cred" + Math.random().toString(36).slice(2);
  const enc = new TextEncoder();
  const head = enc.encode(`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify({ name, parents: [parentId] })}\r\n--${boundary}\r\nContent-Type: ${mime}\r\n\r\n`);
  const tail = enc.encode(`\r\n--${boundary}--\r\n`);
  const body = new Uint8Array(head.length + bytes.length + tail.length); body.set(head, 0); body.set(bytes, head.length); body.set(tail, head.length + bytes.length);
  const res = await fetch("https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true&fields=id,webViewLink", { method: "POST", headers: { Authorization: "Bearer " + token, "Content-Type": `multipart/related; boundary=${boundary}` }, body });
  if (!res.ok) throw new Error(`Drive upload (${res.status}): ${(await res.text()).slice(0, 200)}`);
  return await res.json();
}
function limparNomeArquivo(s: string): string { return String(s || "").replace(/[\\/:*?"<>|]/g, "-").replace(/\s+/g, " ").trim().slice(0, 180); }

/* ===== Relatório PDF (copiado do dd-relatorio-teste, aprovado) ===== */
function limpoPdf(s: string) { return String(s || "").replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}\u{2B00}-\u{2BFF}]/gu, "").replace(/\s+/g, " ").trim(); }
function seloPdf(c: string) { const x = String(c || ""); if (x.includes("🔴") || /reprov/i.test(x)) return { txt: "REPROVADA", cor: rgb(0.75, 0.15, 0.15) }; if (x.includes("🟡") || /ressalv/i.test(x)) return { txt: "RESSALVAS", cor: rgb(0.85, 0.6, 0.05) }; return { txt: "APROVADA", cor: rgb(0.15, 0.55, 0.2) }; }
async function gerarRelatorioPdf(dd: any): Promise<Uint8Array> {
  const doc = await PDFDocument.create();
  const font = await doc.embedFont(StandardFonts.Helvetica); const bold = await doc.embedFont(StandardFonts.HelveticaBold);
  const [PW, PH] = [595.28, 841.89]; const M = 50, W = PW - 2 * M;
  let page = doc.addPage([PW, PH]); let y = PH - M;
  const quebrar = (t: string, f: any, size: number) => { const L: string[] = []; for (const par of String(t).split("\n")) { const ws = par.split(" "); let a = ""; for (const p of ws) { const tt = a ? a + " " + p : p; if (f.widthOfTextAtSize(tt, size) > W) { if (a) L.push(a); a = p; } else a = tt; } L.push(a); } return L; };
  const esc = (t: string, o: any = {}) => { const size = o.size ?? 10.5, f = o.bold ? bold : font, cor = o.cor ?? rgb(0.1, 0.1, 0.1), ind = o.indent ?? 0; for (const ln of quebrar(limpoPdf(t), f, size)) { if (y < M + size + 4) { page = doc.addPage([PW, PH]); y = PH - M; } page.drawText(ln, { x: M + ind, y: y - size, size, font: f, color: cor }); y -= size * 1.4; } };
  const sp = (h = 8) => { y -= h; if (y < M) { page = doc.addPage([PW, PH]); y = PH - M; } };
  const regua = () => { if (y < M + 10) { page = doc.addPage([PW, PH]); y = PH - M; } page.drawLine({ start: { x: M, y: y - 2 }, end: { x: PW - M, y: y - 2 }, thickness: 0.6, color: rgb(0.8, 0.8, 0.8) }); y -= 12; };
  esc("RELATÓRIO DE DUE DILIGENCE — PROCESSOS DO CREDOR", { size: 15, bold: true, cor: rgb(0.12, 0.12, 0.35) }); sp(4);
  esc(`Credor (cedente): ${dd.cedente || "-"}  |  CPF: ${dd.cpf || "-"}`); esc(`Crédito principal em análise: ${dd.credito_principal || "-"}`);
  const g = dd.algum_reprovado ? { t: "ATENÇÃO: há processo com RISCO ao crédito principal — revisão obrigatória.", c: rgb(0.75, 0.15, 0.15) } : { t: "Nenhum processo do credor apresentou risco ao crédito principal.", c: rgb(0.15, 0.55, 0.2) };
  esc(g.t, { size: 11, bold: true, cor: g.c }); esc(`Total de processos avaliados: ${(dd.processos || []).length}`, { size: 9.5, cor: rgb(0.45, 0.45, 0.45) }); sp(6); regua();
  (dd.processos || []).forEach((p: any, i: number) => {
    const q = p.qualificacao || {}; const s = seloPdf(q.classificacao);
    if (y < M + 90) { page = doc.addPage([PW, PH]); y = PH - M; }
    esc(`${i + 1}. Processo ${p.numero}`, { size: 12, bold: true, cor: rgb(0.12, 0.12, 0.35) });
    esc(`Situação (risco ao crédito principal): ${s.txt}`, { size: 11, bold: true, cor: s.cor });
    if ((p.partes || []).length) esc(`Partes: ${(p.partes || []).map(limpoPdf).join("  |  ")}`, { size: 9.5, cor: rgb(0.4, 0.4, 0.4) }); sp(3);
    const r = q.risco_ao_credito_principal || {};
    esc(`Risco ao crédito principal: ${r.tem_risco || "-"}${r.tipo && r.tipo !== "nenhum" ? " (" + r.tipo + ")" : ""}`, { size: 10.5, bold: true });
    if (r.justificativa) esc(r.justificativa, { size: 10, indent: 10 }); sp(3);
    if (q.resumo) { esc("Resumo:", { size: 10.5, bold: true }); esc(q.resumo, { size: 10, indent: 10 }); }
    if ((q.riscos || []).length) { sp(2); esc("Pontos observados:", { size: 10.5, bold: true }); for (const rk of q.riscos) esc(`• [${rk.grau || "-"}] ${rk.risco || ""} — ${rk.fundamento || ""}`, { size: 9.5, indent: 10 }); }
    if (q.observacoes) { sp(2); esc("Observações / o que não pôde ser conferido:", { size: 10, bold: true, cor: rgb(0.5, 0.4, 0.1) }); esc(q.observacoes, { size: 9.5, indent: 10, cor: rgb(0.4, 0.35, 0.2) }); }
    if (p.status && !q.classificacao) esc(`(Não qualificado: ${p.status})`, { size: 9.5, cor: rgb(0.6, 0.3, 0.3) });
    sp(8); regua();
  });
  esc("Relatório gerado por IA a partir dos autos acessíveis na Judit (movimentações e documentos públicos). Documentos sigilosos podem não ter sido conferidos — confira a evidência citada. Revisão humana obrigatória.", { size: 8.5, cor: rgb(0.5, 0.5, 0.5) });
  return await doc.save();
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: CORS });
  try {
    // PORTAO DE ACESSO. Esta function gasta cota da Judit e chamada de IA por
    // processo, e escreve PDF no Drive da casa — deixá-la no verify_jwt padrão
    // significava que qualquer JWT válido servia, inclusive de usuário que o
    // administrador desativou (desativar não invalida o JWT).
    const usuario = await getCallerAtivo(req, serviceClient());
    if (!usuario) return json({ erro: ERRO_ACESSO }, 401);
    const url = new URL(req.url);
    let body: any = {};
    if (req.method === "POST") { try { body = await req.json(); } catch { body = {}; } }
    const getParam = (k: string) => String((body && body[k] != null ? body[k] : url.searchParams.get(k)) || "").trim();
    const cpf = getParam("cpf").replace(/\D/g, "");
    const max = Math.min(parseInt(getParam("max") || "6", 10) || 6, 12);
    const principal = getParam("principal");
    if (!cpf) return json({ erro: "cpf (só números) é obrigatório" }, 400);
    if (!principal) return json({ erro: "principal (número do crédito principal) é obrigatório" }, 400);

    const juditKey = await chaveJudit();
    const anthropicKey = await chaveAnthropic();
    if (!juditKey) return json({ erro: "Chave da Judit não configurada (integracao_judit_secret)." }, 500);
    if (!anthropicKey) return json({ erro: "Chave da Anthropic não configurada (integracao_anthropic_secret)." }, 500);

    // 1) lista os processos do credor
    const lista = await buscarProcessosPorCpf(juditKey, cpf);
    if ((lista as any).erro) return json(lista, 502);
    const processos = (lista as any).processos.slice(0, max);

    // 2) qualifica cada processo pelo Manual — EM PARALELO (pra caber no tempo)
    const resultados = await Promise.all(processos.map(async (p: any) => {
      try {
        const t = await montarTextoProcesso(juditKey, p.numero);
        if ((t as any).aguarde) return { numero: p.numero, partes: p.partes, status: "Judit ainda coletando — rode de novo em ~2 min" };
        if ((t as any).erro || (t as any).nao_encontrado) return { numero: p.numero, partes: p.partes, status: (t as any).erro || "não encontrado" };
        const q = await qualificarPeloManual(anthropicKey, (t as any).texto, principal);
        return { numero: p.numero, partes: p.partes, valor_causa: p.valor_causa, qualificacao: (q as any).ok ? (q as any).veredito : { erro_formato: true, texto_bruto: (q as any).texto_bruto } };
      } catch (e) { return { numero: p.numero, partes: p.partes, status: "erro: " + String((e as Error)?.message || e).slice(0, 80) }; }
    }));

    const algumReprovado = resultados.some((r: any) => r.qualificacao?.risco_ao_credito_principal?.tem_risco === "SIM");

    // Gera o relatório PDF e salva na subpasta "Processos do Credor" do cedente (se vierem os dados da pasta)
    let drive_folder_url: string | null = null, drive_report_url: string | null = null, drive_erro: string | null = null;
    // "intermediador" era o nome antigo do papel. Segue aceito porque esta função
    // é chamada por HTTP de fora do repositório: sem a tolerância, o
    // arquivamento no Drive pararia em silêncio (o if abaixo só é pulado).
    const originador = getParam("originador") || getParam("intermediador");
    const categoria = getParam("categoria") || "Requisições de Pequeno Valor";
    const cedente = getParam("cedente");
    const google = await segredoGoogle();
    if (originador && cedente && google) {
      try {
        const token = await refreshGoogleAccessToken(google.client_id, google.client_secret, google.refresh_token);
        const rootId = await driveEncontrarAnalisesRoot(token);
        const catFolder = await driveFindChildByTolerantName(token, rootId, categoria);
        const catId = catFolder?.id ?? await driveFindOrCreateFolder(token, categoria, rootId);
        const interId = await driveFindOrCreateFolder(token, originador, catId);
        const cedenteId = await driveFindOrCreateFolder(token, cedente, interId);
        const subId = await driveFindOrCreateFolder(token, "Processos do Credor", cedenteId);
        const pdf = await gerarRelatorioPdf({ cpf, credito_principal: principal, cedente, algum_reprovado: algumReprovado, processos: resultados });
        const nome = limparNomeArquivo(`Due Diligence - ${cedente} - processos do credor`) + ".pdf";
        const up = await driveUploadBytes(token, nome, subId, pdf, "application/pdf");
        drive_report_url = up.webViewLink ?? null;
        drive_folder_url = `https://drive.google.com/drive/folders/${subId}`;
      } catch (e) { drive_erro = String((e as Error)?.message || e).slice(0, 200); }
    }

    return json({ cpf, credito_principal: principal, cedente: cedente || null, total_processos_encontrados: (lista as any).processos.length, processos_qualificados: resultados.length, algum_reprovado: algumReprovado, drive_folder_url, drive_report_url, drive_erro, processos: resultados });
  } catch (e) { return json({ erro: String((e as Error)?.message || e) }, 500); }
});
